import http from 'node:http'

http.createServer((req, res) => {
  const url = new URL(req.url || '/', 'http://localhost')
  const code = url.searchParams.get('code') || '1+1'
  const value = eval(code)
  res.end(String(value))
}).listen(0)

import http from 'node:http'
import { exec, execSync } from 'node:child_process'

http.createServer((req, res) => {
  const url = new URL(req.url || '/', 'http://localhost')
  const host = url.searchParams.get('host') || '127.0.0.1'
  const mode = url.searchParams.get('mode') || 'exec'

  // Form A: exec with a built command string
  if (mode === 'exec') {
    const cmd = 'ping -c 1 ' + host
    exec(cmd, (err, stdout) => {
      res.end(err ? String(err) : stdout)
    })
    return
  }

  // Form B: execSync with interpolated command
  try {
    const out = execSync(`ping -c 1 ${host}`, { encoding: 'utf8' })
    res.end(out)
  } catch (err) {
    res.end(String(err))
  }
}).listen(0)

import http from 'node:http'
import serialize from 'node-serialize'

http.createServer((req, res) => {
  const chunks: Buffer[] = []
  req.on('data', (c) => chunks.push(c))
  req.on('end', () => {
    const blob = Buffer.concat(chunks).toString('utf8')
    const session = serialize.unserialize(blob)
    res.end(JSON.stringify(session))
  })
}).listen(0)

import http from 'node:http'
import crypto from 'node:crypto'

http.createServer((_req, res) => {
  const token = crypto.pseudoRandomBytes(16).toString('hex')
  res.end(token)
}).listen(0)

import http from 'node:http'
import fs from 'node:fs'
import path from 'node:path'

http.createServer((req, res) => {
  const url = new URL(req.url || '/', 'http://localhost')
  const file = url.searchParams.get('file') || 'readme.txt'
  const mode = url.searchParams.get('mode') || 'read'
  const target = path.join('/var/data', file)

  // Form A: filesystem read with attacker-controlled path segment
  if (mode === 'read') {
    const content = fs.readFileSync(target, 'utf8')
    res.end(content)
    return
  }

  // Form B: stream the same path back as a file download response
  res.setHeader('Content-Type', 'application/octet-stream')
  res.setHeader('Content-Disposition', 'attachment; filename="' + file + '"')
  fs.createReadStream(target).pipe(res)
}).listen(0)

import http from 'node:http'

http.createServer((req, res) => {
  const url = new URL(req.url || '/', 'http://localhost')
  const input = url.searchParams.get('q') || 'a'
  const re = new RegExp(`^(${input})+$`)
  res.end(String(re.test('aaaaaaaaaaaaaaaaaaaa!')))
}).listen(0)
